// Solarized Dark color ramp: shadow -> mid -> highlight
export const STOPS = [
  { a: 0.47, color: [7, 54, 66] },     // base02 (near-invisible, blends into bg)
  { a: 0.28, color: [88, 110, 117] },  // base01 (dim gray)
  { a: 0.42, color: [38, 139, 210] },  // blue
  { a: 0.42, color: [42, 161, 152] },  // cyan
  { a: 0.40, color: [147, 161, 161] }, // base1
  { a: 0.90, color: [253, 246, 227] }, // base3 (brightest highlight)
];

export const BACKGROUND = "#002b36"; // Solarized base03

function lerp(a, b, t) {
  return a + (b - a) * t;
}

export function colorForAlpha(alpha) {
  const a = Math.max(STOPS[0].a, Math.min(STOPS[STOPS.length - 1].a, alpha));
  for (let i = 0; i < STOPS.length - 1; i++) {
    const s0 = STOPS[i];
    const s1 = STOPS[i + 1];
    if (a >= s0.a && a <= s1.a) {
      const t = (a - s0.a) / (s1.a - s0.a);
      const r = lerp(s0.color[0], s1.color[0], t);
      const g = lerp(s0.color[1], s1.color[1], t);
      const b = lerp(s0.color[2], s1.color[2], t);
      return `rgb(${r | 0}, ${g | 0}, ${b | 0})`;
    }
  }
  return `rgb(${STOPS[STOPS.length - 1].color.join(", ")})`;
}

/**
 * Draws the pixel glow onto an existing <canvas> element.
 * Sizes the canvas automatically to fit the point cloud plus padding.
 *
 * @param {HTMLCanvasElement} canvas
 * @param {Object} [options]
 * @param {number} [options.padding=14]   whitespace around the shape, in px
 * @param {number} [options.cellScale=0.42] pixel-square size relative to grid spacing (0-1)
 * @param {number} [options.alphaBoost=0.15] extra opacity added so dim points still read clearly
 */
export function drawPixelGlow(canvas, options = {}) {
  const { padding = 14, cellScale = 0.42, alphaBoost = 0.15 } = options;
  const points = pixelData;

  const xs = points.map((p) => p.x);
  const ys = points.map((p) => p.y);
  const minX = Math.min(...xs);
  const maxX = Math.max(...xs);
  const minY = Math.min(...ys);
  const maxY = Math.max(...ys);

  const xsSorted = [...new Set(xs)].sort((a, b) => a - b);
  const spacing = xsSorted.length > 1 ? xsSorted[1] - xsSorted[0] : 4;
  const cell = Math.max(2, spacing * cellScale);

  const width = maxX - minX + spacing + padding * 2;
  const height = maxY - minY + spacing + padding * 2;

  const dpr = window.devicePixelRatio || 1;
  canvas.width = width * dpr;
  canvas.height = height * dpr;
  canvas.style.width = `${width}px`;
  canvas.style.height = `${height}px`;

  const ctx = canvas.getContext("2d");
  ctx.scale(dpr, dpr);

  ctx.fillStyle = BACKGROUND;
  ctx.fillRect(0, 0, width, height);

  for (const p of points) {
    const px = p.x - minX + padding - cell / 2;
    const py = p.y - minY + padding - cell / 2;
    ctx.fillStyle = colorForAlpha(p.alpha);
    ctx.globalAlpha = Math.min(1, p.alpha + alphaBoost);
    ctx.fillRect(px, py, cell, cell);
  }
  ctx.globalAlpha = 1;

  return { width, height };
}

export const renderPixelGlow = drawPixelGlow;



